using CsAgentUI;
using CsAgentUI.Endpoints;
using System.Diagnostics;
using System.Text.Json.Nodes;

const string Version = "0.2.0";

if (args.Contains("--version"))
{
    Console.WriteLine($"CSAgent version {Version}");
    return;
}

if (args.Contains("--doc"))
{
    ShowDocumentation();
    return;
}

var builder = WebApplication.CreateBuilder(args);
builder.Logging.SetMinimumLevel(LogLevel.Critical);

var isUiMode = args.Contains("--ui");

// Helper to find memory file from args
static string GetMemoryFile(string[] args)
{
    for (int i = 0; i < args.Length; i++)
        if (args[i] == "--mem" && i + 1 < args.Length) return args[i + 1];

    foreach (var arg in args)
        if (arg != "--ui" && !arg.StartsWith("-")) return arg;

    return "agent_memory.json";
}

// Helper to find model override from args
static string? GetModelOverride(string[] args)
{
    for (int i = 0; i < args.Length; i++)
        if (args[i] == "--model" && i + 1 < args.Length) return args[i + 1];
    return null;
}

var memFile = GetMemoryFile(args);
var modelOverride = GetModelOverride(args);

// ── UI Mode (Web Server) ──
if (isUiMode)
{
    var app = builder.Build();

    // Serve the UI from the embedded string (AOT-safe)
    app.MapGet("/", () => Results.Content(StaticAssets.HtmlUI, "text/html"));

    // Map API endpoints
    app.MapEndpoints(memFile, modelOverride);

    // Register browser launch after server starts
    app.Lifetime.ApplicationStarted.Register(() =>
    {
        Console.WriteLine("\n--- Server started at http://localhost:5050 ---");
        try
        {
            // Attempt to open the default browser
            Process.Start(new ProcessStartInfo("http://localhost:5050") { UseShellExecute = true });
        }
        catch { /* Fail silently if browser cannot be launched */ }
    });

    app.Run("http://localhost:5050");
}

// ── CLI Mode ──
else
{
    UI.Banner();
    Console.WriteLine($"  CSAgent v{Version}");
    Console.WriteLine();
    var apiKey = Environment.GetEnvironmentVariable("ALBERT_API_KEY") ?? "";
    if (string.IsNullOrEmpty(apiKey)) { Console.WriteLine("Error: ALBERT_API_KEY env var not set."); return; }

    var messages = await MemoryStore.LoadAsync(memFile);
    if (messages.Count == 0) messages.Add(CodingAgent.SystemMessage(OperatingSystem.IsWindows()));

    // CLI uses deepseek-v4-flash by default, but can be overridden with --model
    var model = modelOverride ?? "deepseek-v4-flash";
    Console.WriteLine($"  Model: {model}");
    Console.WriteLine();

    // Default to confirm mode for enhanced security (this is now the default in AgentOptions)
    using var agent = new CodingAgent(apiKey, "https://albert.api.etalab.gouv.fr/v1", model, new AgentOptions(Confirm: true), new ConsoleObserver());

    while (true)
    {
        Console.Write("\n> User (type 'exit' to quit): ");
        var input = Console.ReadLine();
        if (string.IsNullOrWhiteSpace(input)) continue;
        if (input.Trim().Equals("exit", StringComparison.OrdinalIgnoreCase)) break;

        messages.Add(new JsonObject { ["role"] = "user", ["content"] = input });
        await agent.RunAsync(messages, memFile);
    }
}

// ── Documentation Display ──

static void ShowDocumentation()
{
    // Use the embedded README content from StaticAssets (AOT-safe)
    var lines = StaticAssets.ReadmeMd.Split(["\r\n", "\n", "\r"], StringSplitOptions.None);

    // Determine terminal width safely
    var termWidth = 80;
    try
    {
        if (!Console.IsOutputRedirected)
            termWidth = Console.WindowWidth;
    }
    catch
    {
        // Fall back to default width
    }

    // Detect if terminal supports ANSI colors
    var useColor = !Console.IsOutputRedirected
                  && (!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("TERM"))
                      || OperatingSystem.IsLinux()
                      || OperatingSystem.IsMacOS());

    foreach (var line in lines)
    {
        var trimmed = line.Trim();

        // ── H1: Title ──
        if (trimmed.StartsWith("# ") && !trimmed.StartsWith("##"))
        {
            var title = trimmed[2..].Trim();
            var sep = new string('=', Math.Min(title.Length, termWidth - 1));
            if (useColor)
            {
                Console.ForegroundColor = ConsoleColor.Cyan;
                Console.WriteLine();
                Console.WriteLine($"  {title}");
                Console.WriteLine($"  {sep}");
                Console.ResetColor();
            }
            else
            {
                Console.WriteLine();
                Console.WriteLine($"  {title}");
                Console.WriteLine($"  {sep}");
            }
            Console.WriteLine();
            continue;
        }

        // ── H2: Section ──
        if (trimmed.StartsWith("## ") && !trimmed.StartsWith("###"))
        {
            var section = trimmed[3..].Trim();
            if (useColor)
            {
                Console.ForegroundColor = ConsoleColor.Green;
                Console.WriteLine($"  {section}");
                Console.ResetColor();
            }
            else
            {
                Console.WriteLine($"  {section}");
            }
            Console.WriteLine();
            continue;
        }

        // ── H3: Sub-section ──
        if (trimmed.StartsWith("### "))
        {
            var sub = trimmed[4..].Trim();
            if (useColor)
            {
                Console.ForegroundColor = ConsoleColor.Yellow;
                Console.WriteLine($"  {sub}");
                Console.ResetColor();
            }
            else
            {
                Console.WriteLine($"  {sub}");
            }
            continue;
        }

        // ── Horizontal rule ──
        if (trimmed == "---")
        {
            var hr = new string('─', Math.Min(60, termWidth - 1));
            if (useColor)
            {
                Console.ForegroundColor = ConsoleColor.DarkGray;
                Console.WriteLine($"  {hr}");
                Console.ResetColor();
            }
            else
            {
                Console.WriteLine($"  {hr}");
            }
            Console.WriteLine();
            continue;
        }

        // ── Unordered list item ──
        if (trimmed.StartsWith("- "))
        {
            var item = trimmed[2..].Trim();
            if (useColor)
            {
                var parts = SplitBold(item);
                Console.Write("  • ");
                foreach (var (text, isBold) in parts)
                {
                    if (isBold)
                    {
                        Console.ForegroundColor = ConsoleColor.White;
                        Console.Write(text);
                        Console.ResetColor();
                    }
                    else
                    {
                        Console.Write(text);
                    }
                }
                Console.WriteLine();
            }
            else
            {
                Console.WriteLine($"  • {item}");
            }
            continue;
        }

        // ── Numbered list item ──
        if (trimmed.Length > 2 && char.IsDigit(trimmed[0]) && trimmed[1] == '.')
        {
            var idx = trimmed.IndexOf(' ');
            var num = trimmed[..idx];
            var item = trimmed[(idx + 1)..].Trim();
            if (useColor)
            {
                Console.ForegroundColor = ConsoleColor.DarkCyan;
                Console.Write($"  {num}.");
                Console.ResetColor();
                Console.WriteLine($" {item}");
            }
            else
            {
                Console.WriteLine($"  {num}. {item}");
            }
            continue;
        }

        // ── Inline code (backtick) ──
        if (trimmed.StartsWith("`") && trimmed.EndsWith("`") && !trimmed.Contains(' '))
        {
            var code = trimmed.Trim('`');
            if (useColor)
            {
                Console.ForegroundColor = ConsoleColor.DarkYellow;
                Console.WriteLine($"  {code}");
                Console.ResetColor();
            }
            else
            {
                Console.WriteLine($"  {code}");
            }
            continue;
        }

        // ── Code block markers ──
        if (trimmed.StartsWith("```"))
        {
            continue;
        }

        // ── Table row ──
        if (trimmed.StartsWith("|") && trimmed.EndsWith("|"))
        {
            var cells = trimmed.Split('|', StringSplitOptions.RemoveEmptyEntries);
            var isHeader = cells.Length > 0 && cells.All(c => c.Trim().All(ch => ch == '-' || ch == ':'));

            if (isHeader)
            {
                if (useColor)
                {
                    Console.ForegroundColor = ConsoleColor.DarkGray;
                    Console.WriteLine($"  {'─',-60}");
                    Console.ResetColor();
                }
                else
                {
                    Console.WriteLine($"  {'─',-60}");
                }
                continue;
            }

            var formatted = string.Join(" │ ", cells.Select(c => c.Trim()));
            if (useColor)
            {
                Console.ForegroundColor = ConsoleColor.DarkGray;
                Console.WriteLine($"  {formatted}");
                Console.ResetColor();
            }
            else
            {
                Console.WriteLine($"  {formatted}");
            }
            continue;
        }

        // ── Bold line (surrounded by **) ──
        if (trimmed.StartsWith("**") && trimmed.EndsWith("**") && trimmed.Length > 4)
        {
            var boldText = trimmed.Trim('*');
            if (useColor)
            {
                Console.ForegroundColor = ConsoleColor.White;
                Console.WriteLine($"  {boldText}");
                Console.ResetColor();
            }
            else
            {
                Console.WriteLine($"  {boldText}");
            }
            continue;
        }

        // ── Regular paragraph ──
        if (!string.IsNullOrWhiteSpace(trimmed))
        {
            if (useColor && trimmed.Contains("**"))
            {
                var parts = SplitBold(trimmed);
                foreach (var (text, isBold) in parts)
                {
                    if (isBold)
                    {
                        Console.ForegroundColor = ConsoleColor.White;
                        Console.Write(text);
                        Console.ResetColor();
                    }
                    else
                    {
                        Console.Write(text);
                    }
                }
                Console.WriteLine();
            }
            else
            {
                Console.WriteLine($"  {trimmed}");
            }
            continue;
        }

        // ── Empty line ──
        Console.WriteLine();
    }

    Console.WriteLine();
}


// Helper to split text by **bold** markers
static List<(string text, bool isBold)> SplitBold(string input)
{
    var result = new List<(string, bool)>();
    var remaining = input;
    while (remaining.Length > 0)
    {
        var boldStart = remaining.IndexOf("**", StringComparison.Ordinal);
        if (boldStart < 0)
        {
            result.Add((remaining, false));
            break;
        }

        if (boldStart > 0)
        {
            result.Add((remaining[..boldStart], false));
        }

        var boldEnd = remaining.IndexOf("**", boldStart + 2, StringComparison.Ordinal);
        if (boldEnd < 0)
        {
            result.Add((remaining[boldStart..], false));
            break;
        }

        var boldContent = remaining[(boldStart + 2)..boldEnd];
        result.Add((boldContent, true));
        remaining = remaining[(boldEnd + 2)..];
    }
    return result;
}

using CsAgentUI;
using System.Text.Json.Nodes;

namespace CsAgentUI.Endpoints;

public static class ApiEndpoints
{
    public static IEndpointRouteBuilder MapEndpoints(this IEndpointRouteBuilder app, string memoryFile, string? modelOverride = null)
    {
        // API endpoint for chat functionality
        app.MapGet("/api/chat", async (HttpContext ctx, string prompt) =>
        {
            ctx.Response.Headers.ContentType = "text/event-stream";

            var observer = new SseObserver(ctx.Response);

            var apiKey = Environment.GetEnvironmentVariable("ALBERT_API_KEY") ?? "";
            if (string.IsNullOrEmpty(apiKey)) 
            { 
                await observer.OnError("API Key not set."); 
                return; 
            }

            var msgs = await MemoryStore.LoadAsync(memoryFile);

            if (msgs.Count == 0) 
                msgs.Add(CodingAgent.SystemMessage(OperatingSystem.IsWindows()));

            msgs.Add(new JsonObject { ["role"] = "user", ["content"] = prompt });

            // Web UI uses Qwen3-Coder by default, but can be overridden with --model
            var model = modelOverride ?? "Qwen/Qwen3-Coder-30B-A3B-Instruct";

            using var agent = new CodingAgent(
                apiKey, 
                "https://albert.api.etalab.gouv.fr/v1", 
                model, 
                new AgentOptions(), 
                observer);

            await agent.RunAsync(msgs, memoryFile);
        });

        return app;
    }
}

using CsAgentUI;
using System.Diagnostics;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace CsAgentUI;

public sealed record AgentOptions(
    int MaxSteps = 30,
    bool DryRun = false,
    bool Confirm = true); // Changed default to true for enhanced security

public sealed class CodingAgent : IDisposable
{
    private readonly LlmClient _client;
    private readonly AgentOptions _opts;
    private readonly IAgentObserver _observer;
    private CancellationTokenSource? _cts;
    private const int ShellTimeoutMs = 60_000;
    private const int TrimThresholdChars = 96_000;

    public CodingAgent(string apiKey, string endpoint, string model, AgentOptions opts, IAgentObserver observer)
    {
        _opts = opts;
        _observer = observer;
        _client = new LlmClient(apiKey, endpoint, model);
    }

    public async Task RunAsync(JsonArray messages, string memoryFile)
    {
        _cts = new CancellationTokenSource();
        var isWindows = OperatingSystem.IsWindows();

        for (int step = 1; step <= _opts.MaxSteps; step++)
        {
            _cts.Token.ThrowIfCancellationRequested();
            await _observer.OnStep(step, _opts.MaxSteps);

            JsonNode response;
            try
            {
                response = await _client.CompleteChatAsync(messages, Tools, _cts.Token);
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception ex)
            {
                await _observer.OnError($"API error: {ex.Message}");
                return;
            }

            var choice = response["choices"]?[0];
            var message = choice?["message"];
            if (message is null)
            {
                await _observer.OnError("Empty response from API.");
                return;
            }

            // Print assistant text
            var text = message["content"]?.GetValue<string>();
            if (!string.IsNullOrWhiteSpace(text))
                await _observer.OnThought(text);

            // Add assistant turn to history
            messages.Add(message.DeepClone());

            var finishReason = choice?["finish_reason"]?.GetValue<string>();
            var toolCalls = message["tool_calls"]?.AsArray();

            if (toolCalls is null || toolCalls.Count == 0)
            {
                if (finishReason == "stop")
                {
                    await _observer.OnDone("Task complete.");
                    await MemoryStore.SaveAsync(memoryFile, messages);
                    return;
                }

                await _observer.OnDone("Assistant finished.");
                return;
            }

            // Execute each tool call
            foreach (var tc in toolCalls)
            {
                if (tc is null) continue;
                _cts.Token.ThrowIfCancellationRequested();

                var callId = tc["id"]?.GetValue<string>() ?? Guid.NewGuid().ToString();
                var funcName = tc["function"]?["name"]?.GetValue<string>() ?? "unknown";
                var argsRaw = tc["function"]?["arguments"]?.GetValue<string>() ?? "{}";

                await _observer.OnToolCall(funcName, PrettyJson(argsRaw));

                string result;
                if (_opts.DryRun)
                {
                    result = "[dry-run] Tool not executed.";
                }
                else if (IsDestructive(funcName))
                {
                    // Always require confirmation for destructive actions
                    // Even if _opts.Confirm is false, we enforce it for safety
                    result = UI.Confirm($"Allow destructive action '{funcName}'?")
                        ? await DispatchAsync(funcName, argsRaw, isWindows)
                        : "Tool call declined by user.";
                }
                else
                {
                    result = await DispatchAsync(funcName, argsRaw, isWindows);
                }

                var isError = result.StartsWith("Error:", StringComparison.OrdinalIgnoreCase)
                           || result.StartsWith("Shell error:", StringComparison.OrdinalIgnoreCase);

                await _observer.OnToolResult(result, isError);

                messages.Add(new JsonObject
                {
                    ["role"] = "tool",
                    ["tool_call_id"] = callId,
                    ["content"] = result
                });
            }

            await MemoryStore.SaveAsync(memoryFile, messages);
            TrimHistory(messages);
        }

        await _observer.OnError($"Reached maximum of {_opts.MaxSteps} steps without completing.");
    }

    private async Task<string> DispatchAsync(string name, string argsJson, bool isWindows)
    {
        try
        {
            var args = JsonNode.Parse(argsJson) ?? new JsonObject();
            return name switch
            {
                "write_file" => WriteFile(
                    args["path"]!.GetValue<string>(),
                    args["content"]!.GetValue<string>()),

                "read_file" => ReadFile(
                    args["path"]!.GetValue<string>()),

                "list_dir" => ListDir(
                    args["path"]?.GetValue<string>() ?? ".",
                    args["recursive"]?.GetValue<bool>() ?? false),

                "sh" => await RunShellAsync(
                    args["cmd"]!.GetValue<string>(), isWindows),

                _ => $"Error: Unknown tool '{name}'"
            };
        }
        catch (Exception ex)
        {
            return $"Error: dispatch failed — {ex.Message}";
        }
    }

    // ── write_file ────────────────────────────────────────────────────────────
    private static string WriteFile(string path, string content)
    {
        try
        {
            var full = Path.GetFullPath(path);
            
            // Additional safety checks for destructive operations
            if (!IsSafePath(full))
            {
                return $"Error: write_file - Path '{full}' is not allowed for writing. Only files in the current working directory are permitted.";
            }
            
            var dir = Path.GetDirectoryName(full);
            if (!string.IsNullOrWhiteSpace(dir)) Directory.CreateDirectory(dir);
            File.WriteAllText(full, content, new UTF8Encoding(false));
            return $"OK: wrote {new FileInfo(full).Length} bytes to '{full}'";
        }
        catch (Exception ex) { return $"Error: write_file — {ex.Message}"; }
    }

    // ── read_file ─────────────────────────────────────────────────────────────
    private static string ReadFile(string path)
    {
        try
        {
            var full = Path.GetFullPath(path);
            
            // Additional safety checks for reading operations
            if (!IsSafePath(full))
            {
                return $"Error: read_file - Path '{full}' is not allowed for reading. Only files in the current working directory are permitted.";
            }
            
            if (!File.Exists(full)) return $"Error: not found '{full}'";
            var len = new FileInfo(full).Length;
            if (len > 512_000) return $"Error: file too large ({len / 1024} KB). Use sh to grep/head.";
            return File.ReadAllText(full, Encoding.UTF8);
        }
        catch (Exception ex) { return $"Error: read_file — {ex.Message}"; }
    }

    // ── list_dir ──────────────────────────────────────────────────────────────
    private static string ListDir(string path, bool recursive)
    {
        try
        {
            var full = Path.GetFullPath(path);
            
            // Additional safety checks for directory operations
            if (!IsSafePath(full))
            {
                return $"Error: list_dir - Path '{full}' is not allowed for listing. Only directories in the current working directory are permitted.";
            }
            
            if (!Directory.Exists(full)) return $"Error: directory not found '{full}'";
            var opt = recursive ? SearchOption.AllDirectories : SearchOption.TopDirectoryOnly;
            var sb = new StringBuilder();
            foreach (var d in Directory.EnumerateDirectories(full, "*", opt))
                sb.AppendLine($"[DIR]  {Path.GetRelativePath(full, d)}/");
            foreach (var f in Directory.EnumerateFiles(full, "*", opt))
                sb.AppendLine($"[FILE] {Path.GetRelativePath(full, f)}  ({Sz(new FileInfo(f).Length)})");
            return sb.Length == 0 ? "(empty)" : sb.ToString().TrimEnd();
        }
        catch (Exception ex) { return $"Error: list_dir — {ex.Message}"; }
    }

    // ── sh ────────────────────────────────────────────────────────────────────
    private static async Task<string> RunShellAsync(string cmd, bool isWindows)
    {
        try
        {
            // Additional safety checks for shell commands
            if (!IsSafeCommand(cmd, isWindows))
            {
                return $"Error: sh - Command '{cmd}' contains potentially dangerous operations and is not allowed.";
            }
            
            var (file, shellArgs) = isWindows
                ? ("cmd.exe", $"/d /s /c \"{cmd}\"")
                : ("/bin/sh", $"-c \"{cmd.Replace("\"", "\\\"")}\"");

            using var proc = new Process
            {
                StartInfo = new ProcessStartInfo
                {
                    FileName = file,
                    Arguments = shellArgs,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    StandardOutputEncoding = Encoding.UTF8,
                    StandardErrorEncoding = Encoding.UTF8
                }
            };

            proc.Start();
            var outTask = proc.StandardOutput.ReadToEndAsync();
            var errTask = proc.StandardError.ReadToEndAsync();
            var waitTask = proc.WaitForExitAsync();

            if (await Task.WhenAny(waitTask, Task.Delay(ShellTimeoutMs)) != waitTask)
            {
                try { proc.Kill(entireProcessTree: true); } catch { /* ignore */ }
                return "Error: command timed out (60s).";
            }

            var output = ((await outTask) + (await errTask)).Trim();
            var prefix = proc.ExitCode == 0 ? $"OK (exit 0):\n" : $"Error (exit {proc.ExitCode}):\n";
            return string.IsNullOrWhiteSpace(output)
                ? prefix.TrimEnd()
                : prefix + output;
        }
        catch (Exception ex) { return $"Shell error: {ex.Message}"; }
    }

    // ── Safety Checks ─────────────────────────────────────────────────────────
    private static bool IsDestructive(string n) => n is "write_file";

    // Check if path is safe (only allows files in current working directory)
    private static bool IsSafePath(string fullPath)
    {
        try
        {
            var currentDir = Directory.GetCurrentDirectory();
            var normalizedCurrent = Path.GetFullPath(currentDir).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            var normalizedPath = Path.GetFullPath(fullPath).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            
            // Allow only paths that are within the current directory or subdirectories
            return normalizedPath.StartsWith(normalizedCurrent, StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            // If we can't determine safety, be conservative and disallow
            return false;
        }
    }

    // Check if command is potentially dangerous (platform-aware)
    private static bool IsSafeCommand(string cmd, bool isWindows)
    {
        var lowerCmd = cmd.ToLowerInvariant();

        if (isWindows)
        {
            // Windows-specific dangerous patterns
            var windowsDangerous = new[]
            {
                "format ",          // Format drive
                "format.",          // Format drive (with dot)
                "del /f",           // Force delete files
                "del /s",           // Recursive delete
                "rd /s",            // Force remove directory tree
                "rmdir /s",         // Force remove directory tree
                "reg delete",       // Registry manipulation
                "reg add",          // Registry manipulation
                "reg import",       // Registry import
                "net user",         // User management
                "net localgroup",   // Group management
                "net share",        // Share management
                "net use",          // Network drive mapping
                "takeown",          // Take ownership
                "icacls",           // Permission changes
                "cacls",            // Permission changes
                "attrib -r -s -h",  // Remove read-only/system/hidden attributes (often used by malware)
                "bcdedit",          // Boot configuration
                "diskpart",         // Disk partitioning
                "powershell start-process -verb runas", // Privilege escalation via PowerShell
                "runas",            // Run as different user
                "shutdown",         // System shutdown
                "reboot",           // System reboot
                "\\windows\\system32\\", // System directory (case-insensitive match via lowercase)
                "\\windows\\system\\",   // System directory
                "\\program files\\",     // Program Files (shouldn't write there)
            };

            foreach (var pattern in windowsDangerous)
            {
                if (lowerCmd.Contains(pattern))
                {
                    return false;
                }
            }
        }
        else
        {
            // Unix-specific dangerous patterns
            var unixDangerous = new[]
            {
                "sudo ",            // Privilege escalation
                "chmod",            // Permission changes
                "shutdown",         // System shutdown
                "reboot",           // System reboot
                "dd ",              // Low-level disk operations
                "mkfs",             // File system creation
                "/etc/",            // System configuration files
                "/usr/bin/",        // System binaries
                "/bin/",            // System binaries
            };

            foreach (var pattern in unixDangerous)
            {
                if (lowerCmd.Contains(pattern))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private static string PrettyJson(string raw)
    {
        try { return JsonNode.Parse(raw)?.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) ?? raw; }
        catch { return raw; }
    }

    private static string Sz(long b) =>
        b < 1024 ? $"{b} B" : b < 1_048_576 ? $"{b / 1024} KB" : $"{b / 1_048_576} MB";

    private static void TrimHistory(JsonArray msgs)
    {
        static int Len(JsonNode? m)
        {
            var c = m?["content"];
            return c is JsonValue v ? v.GetValue<string>().Length : (c?.ToJsonString().Length ?? 0);
        }
        int total = msgs.Sum(Len);
        while (total > TrimThresholdChars && msgs.Count > 3)
        {
            total -= Len(msgs[1]);
            msgs.RemoveAt(1);
        }
    }

