        --border:rgba(255,255,255,.10);
        --primary:#4da3ff;
        --primary-glow:rgba(77,163,255,.35);
        --text:#f8fafc;
        --muted:#94a3b8;
        --thought:#fbbf24;
        --call:#38bdf8;
        --result:#4ade80;
        --done:#22c55e;
        --warning:#f59e0b;
        --danger:#ef4444;
    }

    *{
        box-sizing:border-box;
    }

