    header{
        height:75px;
        padding:0 30px;
        display:flex;
        align-items:center;
        justify-content:space-between;
        border-bottom:1px solid var(--border);
        background:rgba(255,255,255,.03);
    }

    .brand{
        display:flex;
        align-items:center;
        gap:14px;
    }

    h2{
        margin:0;
        display:flex;
        align-items:center;
        gap:10px;
        font-family:"JetBrains Mono",monospace;
        font-size:15px;
